
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mbeefvdw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mbeefvdw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.778542744083357e+00, -4.681956431905710e+00, -4.546606100584532e+00, -4.359094827142942e+00, -4.103559761979624e+00, -3.763440293141425e+00, -3.325763722067888e+00, -2.789151701529923e+00, -2.175373125400591e+00, -1.517319473277020e+00, -9.284304151118801e-01, -6.633162009853723e-01, -6.259869796112284e-01, -5.283542115229491e-01, -3.633318321625668e-01, -2.086052679376232e-01, -1.007429391253656e-01, -3.440062662426711e-02, -7.361004465535606e-03, -6.585405406838578e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


